struct acrn_ioreq_client * acrn_ioreq_client_create ( struct acrn_vm * vm , ioreq_handler_t handler , void * priv , bool is_default , const char * name ) { struct acrn_ioreq_client * client ; if ( ! handler && ! is_default ) { dev_dbg ( acrn_dev . this_device , "Cannot create non-default client w/o handler!\n" ) ; return NULL ; } client = kzalloc ( sizeof ( * client ) , GFP_KERNEL ) ; if ( ! client ) { return NULL ; } client -> handler = handler ; client -> vm = vm ; client -> priv = priv ; client -> is_default = is_default ; rwlock_init ( & client -> range_lock ) ; INIT_LIST_HEAD ( & client -> range_list ) ; init_waitqueue_head ( & client -> wq ) ; if ( client -> handler ) { client -> thread = kthread_run ( ioreq_task , client , "VM%u-%s" , client -> vm -> vmid , client -> name ) ; if ( IS_ERR ( client -> thread ) ) { kfree ( client ) ; return NULL ; } } spin_lock_bh ( & vm -> ioreq_clients_lock ) ; if ( is_default ) { vm -> default_client = client ; } else { list_add ( & client -> list , & vm -> ioreq_clients ) ; } spin_unlock_bh ( & vm -> ioreq_clients_lock ) ; dev_dbg ( acrn_dev . this_device , "Created ioreq client %s.\n" , name ) ; return client ; } 